def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()


def _assert_tenant(obj, user: User) -> None:
    """Raise 404 if ``obj`` doesn't belong to ``user``'s org.

    Returns 404 (not 403) so the mere existence of another tenant's
    resources can't be inferred — closes the IDOR vector on the
    automation read/download endpoints.
    """
    org_id = getattr(user, "org_id", None)
    if org_id is not None and getattr(obj, "org_id", None) != org_id:
        raise HTTPException(status_code=404, detail="Not found")


_PREVIEWABLE_FILE_TYPES = {
    "csv", "docx", "gif", "htm", "html", "jpeg", "jpg", "json", "md",
    "pdf", "png", "pptx", "svg", "txt", "webp", "xlsx",
}


def _serialize_automation_file(file_record: AutomationFile) -> dict:
    """Return one stable deliverable payload for run, chat, and file views."""
    file_type = (file_record.file_type or Path(file_record.name).suffix).lower().lstrip(".")
    file_url = file_record.file_url or f"/api/automations/files/{file_record.id}/download"
    mime_type = file_record.mime_type or mimetypes.guess_type(file_record.name)[0]
    created_date = getattr(file_record, "created_date", None)
    if hasattr(created_date, "isoformat"):
        created_date = created_date.isoformat()

    return {
        "id": file_record.id,
        "automation_file_id": file_record.id,
        "name": file_record.name,
        "file_name": file_record.name,
        "type": file_type,
        "file_type": file_type,
        "mime_type": mime_type,
        "size": file_record.size,
        "file_size": file_record.size,
        "url": file_url,
        "file_url": file_url,
        "preview_url": f"/api/automations/files/{file_record.id}/preview",
        "has_preview": file_type in _PREVIEWABLE_FILE_TYPES,
        "source": "automation_file",
        "created_date": created_date,
    }


def _chat_message_artifacts_for_files(files: list[AutomationFile]) -> list[dict]:
    """Map ``AutomationFile`` rows onto the artifact shape the chat surface
    already understands.

    The chat-side ``ArtifactCardList`` was built around artifact payloads from
    live chat runs. The deliverable serializer (above) is the same shape plus
    a few extras (``has_preview``, ``created_date``) the card list gracefully
    ignores, so we use it directly and add the chat-friendly ``title`` alias
    so cards keep showing the file name when ``title`` is what they read.
    """
    return [
        {
            "id": f.id,
            "artifact_id": f.id,
            "automation_file_id": f.id,
            "title": f.name,
            "name": f.name,
            "file_name": f.name,
            "type": (f.file_type or Path(f.name).suffix).lower().lstrip("."),
            "file_type": (f.file_type or Path(f.name).suffix).lower().lstrip("."),
            "file_size": f.size,
            "size": f.size,
            "url": f.file_url or f"/api/automations/files/{f.id}/download",
            "file_url": f.file_url or f"/api/automations/files/{f.id}/download",
            "preview_url": f"/api/automations/files/{f.id}/preview",
            "has_preview": (f.file_type or Path(f.name).suffix).lower().lstrip(".")
            in _PREVIEWABLE_FILE_TYPES,
            "source": "automation_file",
        }
        for f in files
    ]


# ---------------------------------------------------------------------------
# Schedules
# ---------------------------------------------------------------------------

class ParseScheduleRequest(BaseModel):
    schedule: str
    timezone: str | None = None


@router.post("/parse-schedule")
def parse_schedule_endpoint(req: ParseScheduleRequest):
    """Parse a free-form schedule string into a cron expression + next run time.

    ``timezone`` (optional IANA name, e.g. "Asia/Shanghai") controls which
    timezone the cron is interpreted in; the returned ``next_run_at`` is
    always UTC-naive so the client can display it in the user's locale.
    """
    from app.services.schedule_parser import parse_schedule, next_run_at, describe_schedule
    try:
        cron = parse_schedule(req.schedule)
        nxt = next_run_at(cron, tz_name=req.timezone)
        return {
            "success": True,
            "cron": cron,
            "next_run_at": nxt.isoformat(),
            "description": describe_schedule(cron),
            "timezone": req.timezone or "UTC",
        }
    except Exception as e:
        return {"success": False, "error": str(e)}


# ---------------------------------------------------------------------------
# Per-session panel (Manus-style "Scheduled" side panel)
# ---------------------------------------------------------------------------

@router.get("/by-session/{session_id}")
def get_automation_by_session(
    session_id: str,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_required),
):
    """Return the AutomationTask linked to a chat session, plus its recent
    executions. Used by the Manus-style "Scheduled" side panel that appears
    only in chat sessions that have an automation.

    Returns ``{"task": null}`` if the session has no automation — the
    frontend uses this to decide whether to render the Scheduled button.

    Scoped to the caller's org so one tenant can't enumerate another's
    automations by guessing session ids.
    """
    task = db.query(AutomationTask).filter(
        AutomationTask.session_id == session_id,
        AutomationTask.org_id == user.org_id,
        AutomationTask.is_deleted == False,  # noqa: E712
    ).order_by(AutomationTask.created_date.desc()).first()
    if not task:
        return {"task": None, "executions": []}

    # Attach the last N executions with their file counts.
    rows = db.query(AutomationExecution).filter(
        AutomationExecution.automation_task_id == task.id,
        AutomationExecution.is_deleted == False,  # noqa: E712
    ).order_by(AutomationExecution.created_date.desc()).limit(20).all()

    executions = []
    for r in rows:
        d = r.to_dict()
        files = db.query(AutomationFile).filter(
            AutomationFile.execution_id == r.id,
            AutomationFile.is_deleted == False,  # noqa: E712
        ).all()
        d["files"] = [_serialize_automation_file(f) for f in files]
        d["file_count"] = len(files)
        # Phase 5 (Tier A #2): surface the quality-gate decision + held_back
        # flag so the Scheduled panel can explain why a completed run has no
        # deliverable file (low-confidence output was held back).
        _qg = (
            (r.output_data or {}).get("quality_gate")
            if isinstance(r.output_data, dict) else None
        )
        d["quality_gate"] = _qg
        d["held_back"] = bool(_qg and not _qg.get("passed", True))
        # Per-run conversation id — surfaced explicitly for the run-log
        # "Open in chat" deep-link (the executor creates one conversation
        # per execution, stored in output_data.conversation_id).
        d["conversation_id"] = (
            (r.output_data or {}).get("conversation_id")
            if isinstance(r.output_data, dict) else None
        )
        executions.append(d)

    return {
        "task": task.to_dict(),
        "executions": executions,
    }


def _ext_from_url(file_url: str | None) -> str:
    """Extract lowercase file extension from a URL, default to 'docx'."""
    import re
    if not file_url:
        return "docx"
    m = re.search(r"\.([a-z0-9]+)(?:\?|$)", file_url, re.IGNORECASE)
    return m.group(1).lower() if m else "docx"


def _report_resource_kind(report_type: str | None, file_type: str) -> str:
    """Map Report.type + file extension to a resource_kind value.

    - ``dashboard`` → ``"dashboard"`` (triggers DashboardArtifactPreview)
    - ``html``/``htm`` extension → ``"html_file"`` (triggers sandbox iframe)
    - everything else → ``"report"``
    """
    rt = (report_type or "").lower()
    if rt == "dashboard":
        return "dashboard"
    if file_type in ("html", "htm"):
        return "html_file"
    return "report"


@router.get("/by-session/{session_id}/files")
def list_files_by_session(
    session_id: str,
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_required),
):
    """Return the AutomationTask (if any) for this chat session plus every file
    reachable from it.

    Primary list: AI-generated ``AutomationFile`` rows from all executions of the
    session's task. ``_source="ai_generated"`` so the UI can label them.
    Secondary list: any ``UserFile`` rows uploaded to this session, with
    ``_source="uploaded"`` (kept so chat uploads still surface even when the
    session has no automation).

    Used by the chat-side "Files in this task" panel so triggered automation
    runs surface their generated artifacts even though executions aren't
    visible in chat. Scoped to the caller's org, mirroring ``/by-session``.
    """
    task = db.query(AutomationTask).filter(
        AutomationTask.session_id == session_id,
        AutomationTask.org_id == user.org_id,
        AutomationTask.is_deleted == False,  # noqa: E712
    ).order_by(AutomationTask.created_date.desc()).first()

    files: list[dict] = []

    if task:
        rows = db.query(AutomationFile).filter(
            AutomationFile.automation_task_id == task.id,
            AutomationFile.is_deleted == False,  # noqa: E712
        ).order_by(AutomationFile.created_date.desc()).limit(200).all()
        for f in rows:
            d = _serialize_automation_file(f)
            d["_source"] = "ai_generated"
            d["execution_id"] = f.execution_id
            files.append(d)

    # UserFile uploads for this session (secondary; lets manual uploads show
    # even when no task is linked to the session).
    user_rows = db.query(UserFile).filter(
        UserFile.session_id == session_id,
        UserFile.is_deleted == False,  # noqa: E712
    ).order_by(UserFile.updated_date.desc()).limit(200).all()
    for u in user_rows:
        d = u.to_dict()
        d["_source"] = "uploaded"
        files.append(d)

    # Report rows for this session (agent-generated DOCX reports created in
    # chat via create_resource type=report). Normalize to same shape as
    # AutomationFile/UserFile so the frontend ChatFilesModal renders them
    # without any code change.
    from app.models.report import Report as ReportModel
    report_rows = db.query(ReportModel).filter(
        ReportModel.session_id == session_id,
        ReportModel.is_deleted == False,  # noqa: E712
    ).order_by(ReportModel.updated_date.desc()).limit(200).all()
    for r in report_rows:
        # Derive file_type from file_url extension; default to docx
        ft = _ext_from_url(r.file_url)
        # Derive resource_kind: dashboard/HTML get special treatment;
        # everything else is "report"
        kind = _report_resource_kind(r.type, ft)
        files.append({
            "id": r.id,
            "name": r.title,
            "file_type": ft,
            "file_url": r.file_url,
            "source": "ai_generated",
            "resource_kind": kind,
            "project": r.project,
            "project_id": r.project_id,
            "session_id": r.session_id,
            "agent_name": r.agent_name,
            "updated_date": r.updated_date.isoformat() if r.updated_date else None,
            "created_date": r.created_date.isoformat() if r.created_date else None,
            "_source": "ai_generated",
            "_entity_type": "Report",
        })

    # Artifacts stored in chat_messages.artifacts JSON column for this session.
    # The agent stores generated files (DOCX, PDF, HTML) as Artifacts in
    # chat_messages.artifacts (per-message), not always as Report entities.
    # Include them here so the "Files in this task" modal surfaces everything
    # the agent produced in this session.
    from app.models.chat_message import ChatMessage
    seen_artifact_ids: set[str] = set()
    msg_rows = db.query(ChatMessage).filter(
        ChatMessage.session_id == session_id,
        ChatMessage.is_deleted == False,  # noqa: E712
        ChatMessage.artifacts.isnot(None),
    ).all()
    for m in msg_rows:
        arts = m.artifacts
        if not isinstance(arts, list):
            continue
        for art in arts:
            if not isinstance(art, dict):
                continue
            aid = str(art.get("artifact_id") or art.get("id") or "")
            if not aid or aid in seen_artifact_ids:
                continue
            seen_artifact_ids.add(aid)
            raw_file_url = art.get("file_url") or ""
            raw_preview_url = art.get("preview_url") or ""
            ft = _ext_from_url(raw_file_url) or (art.get("type") or "").lower() or "docx"
            kind = _report_resource_kind(art.get("type"), ft)
            # For Office formats (DOCX/PPTX/XLSX), prefer the HTML preview
            # variant (mammoth/pptx-renderer) which renders cleanly inline
            # in a sandboxed iframe. Fall back to PDF preview, then to the
            # raw file_url (which is the download endpoint and will
            # trigger a download instead of rendering).
            OFFICE = {"doc", "docx", "ppt", "pptx", "pps", "ppsx", "xls", "xlsx", "odt", "ods", "odp", "rtf"}
            is_office = ft in OFFICE
            primary_url = raw_file_url
            if is_office and raw_preview_url:
                # If the preview URL points at the artifact preview endpoint
                # (ends with /preview), append ?format=html so the user gets
                # the mammoth/pptx HTML rendition (clean inline render)
                # instead of a PDF (which would still work but feels heavy
                # in a small modal).
                if ft in ("docx", "pptx"):
                    if "?" in raw_preview_url:
                        primary_url = raw_preview_url + "&format=html"
                    else:
                        primary_url = raw_preview_url + "?format=html"
                else:
                    # XLSX: no HTML preview, use cached PDF instead
                    primary_url = raw_preview_url
            elif not is_office and raw_preview_url:
                # PDF/image previews: use the cached preview blob directly
                primary_url = raw_preview_url
            files.append({
                "id": aid,
                "name": art.get("title") or art.get("file_name") or "Artifact",
                "file_type": ft,
                "file_url": primary_url or raw_file_url,
                "preview_url": raw_preview_url,
                "download_url": raw_file_url,
                "file_size": art.get("file_size"),
                "mime_type": art.get("mime_type"),
                "source": "ai_generated",
                "resource_kind": kind,
                "session_id": session_id,
                "agent_name": m.role if m.role == "assistant" else None,
                "message_id": m.id,
                "updated_date": m.updated_date.isoformat() if m.updated_date else None,
                "created_date": m.created_date.isoformat() if m.created_date else None,
                "_source": "ai_generated",
                "_entity_type": "Artifact",
            })

    return {
        "task_id": task.id if task else None,
        "task_name": task.name if task else None,
        "files": files,
    }


