class ToggleRequest(BaseModel):
    status: str  # "active" or "paused"


@router.post("/{task_id}/toggle")
def toggle_status(task_id: str, req: ToggleRequest, db: Session = Depends(get_db)):
    """Pause/resume an automation. If resuming, recompute next_run_at."""
    task = db.query(AutomationTask).filter(
        AutomationTask.id == task_id,
        AutomationTask.is_deleted == False,
    ).first()
    if not task:
        raise HTTPException(status_code=404, detail="Automation task not found")
    new_status = req.status
    if new_status not in ("active", "paused", "failed", "completed"):
        raise HTTPException(status_code=400, detail=f"Invalid status: {new_status}")
    task.status = new_status
    task.updated_date = datetime.now(timezone.utc)
    db.commit()
    if new_status == "active" and task.cron_expression:
        from app.services.automation_dispatcher import recompute_next_run
        nxt = recompute_next_run(task_id)
        if nxt:
            return {
                "success": True,
                "status": new_status,
                "next_run_at": nxt.isoformat(),
            }
    return {
        "success": True,
        "status": new_status,
        "next_run_at": task.next_run_at.isoformat() if task.next_run_at else None,
    }


@router.delete("/{task_id}")
def delete_automation(task_id: str, db: Session = Depends(get_db)):
    """Soft-delete an automation task. Used by the Manus-style
    'Delete schedule' action in the Scheduled side panel.

    Also clears the chat_session → task link by stamping a sentinel on
    the session's metadata so the Scheduled button disappears for the
    originating chat.
    """
    task = db.query(AutomationTask).filter(
        AutomationTask.id == task_id,
        AutomationTask.is_deleted == False,  # noqa: E712
    ).first()
    if not task:
        raise HTTPException(status_code=404, detail="Automation task not found")
    task.is_deleted = True
    task.status = "deleted"
    task.updated_date = datetime.now(timezone.utc)
    db.commit()
    return {"success": True, "id": task_id}


# ── Nightly forecast bootstrap ─────────────────────────────────────────


@router.post("/bootstrap-nightly-forecast")
def bootstrap_nightly_forecast(
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user_required),
):
    """Create the idempotent nightly forecast automation task.

    Ensures:
      1. Forecast targets exist (seeded from per-app domain config)
      2. The automation_runtime_agent exists for this (org, app)
      3. An AutomationTask with cron=0 2 * * *, skip_confirmation=true exists

    Returns the existing task if already created. Idempotent.
    """
    from app.config import settings

    if not getattr(settings, "NIGHTLY_FORECAST_ENABLED", True):
        raise HTTPException(status_code=403, detail="Nightly forecast is disabled")

    from app.services.automation_runtime import ensure_automation_runtime_agent
    from app.services.forecasting.seed_targets import (
        seed_forecast_targets,
        discover_and_seed_sku_targets,
    )

    org_id = getattr(user, "org_id", None) or "default-org"
    app_id = getattr(user, "app_id", None) or "default-app"
    cron = getattr(settings, "NIGHTLY_FORECAST_CRON", "0 2 * * *")

    # 1. Ensure targets exist (idempotent)
    seed_forecast_targets(db, org_id=org_id, app_id=app_id)
    # 1b. Discover and seed ERP SKU targets (idempotent)
    sku_count = discover_and_seed_sku_targets(db, org_id=org_id, app_id=app_id)
    if sku_count:
        logger.info("[bootstrap] Seeded %d new ERP SKU targets for org=%s", sku_count, org_id)

    # 2. Ensure runtime agent exists (idempotent)
    runtime = ensure_automation_runtime_agent(db, org_id, app_id)

    # 3. Find or create the automation task (idempotent by name + org)
    existing = db.query(AutomationTask).filter(
        AutomationTask.name == "Nightly Forecast",
        AutomationTask.org_id == org_id,
        AutomationTask.is_deleted == False,  # noqa: E712
    ).first()
    if existing:
        return {"task_id": existing.id, "status": "exists", "cron": cron}

    task = AutomationTask(
        name="Nightly Forecast",
        type="scheduled",
        description=(
            "Silent nightly ML forecast for all active forecast targets "
            "in this org. Writes to forecast_runs."
        ),
        org_id=org_id,
        app_id=app_id,
        agent_id=runtime.id,
        created_by_id=getattr(user, "id", None),
        schedule=cron,
        cron_expression=cron,
        timezone="UTC",
        skip_confirmation="true",
        output_format="json",
        prompt=(
            "Run the `forecast_run` tool with no arguments (target_id=null) "
            "to refresh forecasts for all active targets in this org. "
            "Do not chat, summarize, or output any narrative — just call the "
            "tool, report success/failure counts, and end."
        ),
        status="active",
    )
    db.add(task)
    db.commit()
    db.refresh(task)
    return {"task_id": task.id, "status": "created", "cron": cron}


class NotificationSettingsRequest(BaseModel):
    notify_enabled: bool = False
    notify_emails: list[str] = []
    notify_on: str = "always"  # "always" | "on_success" | "on_failure"
    attach_file: bool = True


@router.patch("/{task_id}/notification-settings")
def update_notification_settings(
    task_id: str,
    req: NotificationSettingsRequest,
    db: Session = Depends(get_db),
):
    """Persist per-task email notification settings with server-side validation.

    Rejects malformed addresses and unknown ``notify_on`` values with 422 so the
    UI can surface inline errors without a round-trip to the SMTP server.
    """
    from app.services.notification_gateway import is_valid_email

    task = db.query(AutomationTask).filter(
        AutomationTask.id == task_id,
        AutomationTask.is_deleted == False,  # noqa: E712
    ).first()
    if not task:
        raise HTTPException(status_code=404, detail="Automation task not found")

    emails = [e.strip().lower() for e in req.notify_emails if e and e.strip()]
    invalid = [e for e in emails if not is_valid_email(e)]
    if invalid:
        raise HTTPException(
            status_code=422,
            detail=f"Invalid email address(es): {', '.join(invalid)}",
        )
    if req.notify_on not in ("always", "on_success", "on_failure"):
        raise HTTPException(
            status_code=422,
            detail="notify_on must be one of: always, on_success, on_failure",
        )

    task.notify_enabled = req.notify_enabled
    task.notify_emails = emails
    task.notify_on = req.notify_on
    task.attach_file = req.attach_file
    task.updated_date = datetime.now(timezone.utc)
    db.commit()
    db.refresh(task)
    return {
        "success": True,
        "notify_enabled": task.notify_enabled,
        "notify_emails": task.notify_emails,
        "notify_on": task.notify_on,
        "attach_file": task.attach_file,
    }


